import { nanoid } from 'nanoid';
export const byId = (id) => (item) => {
    return item.id === id;
};
export const makeCreate = (collection) => (data) => {
    const now = +new Date();
    const item = {
        id: nanoid(5),
        created: now,
        data,
    };
    collection.push(item);
    return item;
};
export const makeUpdate = (collection) => (id, data) => {
    const itemToUpdate = collection.find(byId(id));
    if (itemToUpdate === undefined) {
        return {
            success: false,
            errorCode: 'CRUD_UNABLE_TO_FIND_ITEM',
            reason: `Unable to find item with ID ${id}`,
        };
    }
    itemToUpdate.updated = +new Date();
    itemToUpdate.data = {
        ...itemToUpdate.data,
        ...data,
    };
    return {
        success: true,
        value: itemToUpdate,
    };
};
export const makeDelete = (collection) => (id) => {
    const index = collection.findIndex(byId(id));
    if (index === -1) {
        return {
            success: false,
            errorCode: 'CRUD_UNABLE_TO_FIND_ITEM',
            reason: `Unable to find item with ID ${id}`,
        };
    }
    collection.splice(index, 1);
    return {
        success: true,
        value: true,
    };
};
export const makeRestore = (collection) => (item) => {
    const index = collection.findIndex(byId(item.id));
    if (index !== -1) {
        return {
            success: false,
            errorCode: 'CRUD_ITEM_EXISTS',
            reason: `Item with ID ${item.id} already exists`,
        };
    }
    collection.push(item);
    return {
        success: true,
        value: true,
    };
};
export const isItem = (value) => {
    return value['id'] && value['created'] && value['data'];
};
