import { createExternalMessage } from '@vocably/hermes';
const scope = 'authStorage';
export const [setItem, onSetItemRequest] = createExternalMessage(`${scope}.setItem`);
export const [removeItem, onRemoveItemRequest] = createExternalMessage(`${scope}.removeItem`);
export const [getAll, onGetAllRequest] = createExternalMessage(`${scope}.getAll`);
export const [clear, onClearRequest] = createExternalMessage(`${scope}.clear`);
