const keyPrefix = '@Auth_';
const createStorageKey = (key) => `${keyPrefix}${key}`;
const isStorageKey = (key) => key.startsWith(keyPrefix);
const getKey = (storageKey) => storageKey.replace(keyPrefix, '');
export const setItems = (storage, items) => storage.set(Object.entries(items).reduce((acc, [key, value]) => (Object.assign(Object.assign({}, acc), { [createStorageKey(key)]: value })), {}));
export const removeItems = (storage, keys) => storage.remove(keys.map(createStorageKey));
export const getAll = (storage) => storage.get().then((data) => Object.entries(data).reduce((acc, [storageKey, value]) => {
    if (!isStorageKey(storageKey)) {
        return acc;
    }
    return Object.assign(Object.assign({}, acc), { [getKey(storageKey)]: value });
}, {}));
export const clearAll = (storage) => storage
    .get()
    .then((allData) => storage.remove(Object.keys(allData).filter(isStorageKey)));
