import { explode, join } from '@vocably/sulna';
import { merge } from 'lodash-es';
import { byCard, equalCards } from './compareCards';
import { analysisItemToCard } from './analysisItemToCard';
export const getCardCandidates = (collection, cardCandidates) => {
    return cardCandidates.map((card) => {
        const existingItem = collection.find(byCard(card));
        if (existingItem === undefined) {
            return {
                data: card,
            };
        }
        return merge({ data: card }, existingItem);
    });
};
export const combineCards = (acc, card) => {
    const existingIndex = acc.findIndex(equalCards(card));
    if (existingIndex === -1) {
        return [...acc, card];
    }
    return acc.map((existingCard, index) => {
        if (index !== existingIndex) {
            return existingCard;
        }
        return {
            ...existingCard,
            definition: join([
                ...explode(existingCard.definition),
                ...explode(card.definition),
            ]),
        };
    });
};
export const createTranslationCards = ({ collection, analysisItems, language, }) => {
    return getCardCandidates(collection, analysisItems
        .map((analysisItem) => analysisItemToCard({
        language,
        analysisItem,
    }))
        .reduce(combineCards, []));
};
