import { getUserMetadata as apiGetUserMetadata, saveUserMetadata as apiSaveUserMetadata, } from '@vocably/api';
let userMetadata = null;
export const getUserMetadata = async () => {
    if (userMetadata !== null) {
        return {
            success: true,
            value: userMetadata,
        };
    }
    const result = await apiGetUserMetadata();
    if (result.success === false) {
        return result;
    }
    userMetadata = result.value;
    return {
        success: true,
        value: result.value,
    };
};
export const invalidateUserMetadata = () => {
    userMetadata = null;
};
export const saveUserMetadata = async (payloadMetadata) => {
    userMetadata = payloadMetadata;
    return apiSaveUserMetadata(payloadMetadata);
};
